function skillView(id){
 const s=db.skills.find(x=>x.id===id);if(!s)return go('catalog');
 const groups=[['Входные данные',s.inputs],['Пошаговый алгоритм',s.steps],['Условия решения',s.decisions],['Исключения',s.exceptions],['Инструменты',s.tools],['Ожидаемый результат',[s.expectedResult]],['Допустимые действия',s.allowedAutomation],['Источники',s.sources],['Неизвестные сведения',s.unknowns]];
 const items=(arr)=>arr?.length?`<div class="detail-list">${arr.map((item,i)=>{const x=typeof item==='string'?{statement:item}:item||{};return `<div class="detail-item"><b>${String(i+1).padStart(2,'0')}</b><div><strong>${esc(x.statement||'Не указано')}</strong>${x.evidence?`<small>Основание: «${esc(x.evidence)}»</small>`:''}</div>${x.needsValidation?badge('Проверить','amber'):''}</div>`}).join('')}</div>`:'<div class="empty">Пока не указано.</div>';
 const launch=s.approved?`<button class="button primary" data-action="run-skill" data-id="${esc(id)}">${s.kind?'▷ Запустить':'Обсудить с двойником'}</button>`:'';
 const runs=db.operations.filter(o=>o.skillId===s.id||o.operation===s.kind).length;
 const related=db.skills.filter(x=>x.id!==s.id).slice(0,2);
 const more=groups.map(([title,arr])=>`<section class="skill-detail-section"><h3>${title}</h3>${items(arr)}</section>`).join('');
 shell(`<div class="eyebrow">КАТАЛОГ НАВЫКОВ / ${esc(s.id)}</div>${heading(s.title,s.purpose||'Учебный Skill цифрового сотрудника.',launch)}<div class="skill-meta"><span>${badge(s.approved?'Подтверждён · демо':'Черновик',s.approved?'green':'amber')}</span><span>Версия ${esc(s.version)}</span><span>Автор: ${esc(s.author)}</span></div><nav class="skill-tabs"><button class="active" type="button">Обзор</button><button type="button" data-action="show-skill-details">Структура навыка</button><button type="button" data-action="history" data-id="${esc(id)}">Версии</button></nav><div class="skill-overview-grid"><div class="card skill-cover" role="img" aria-label="Иллюстрация навыка"></div><section class="card skill-features"><h2>Ключевые возможности</h2>${(s.steps||[]).slice(0,4).map(x=>`<div class="feature-line"><span>${iconSvg('check')}</span>${esc(x)}</div>`).join('')}</section><section class="card skill-usage"><h2>Использование</h2><strong>${runs}</strong><span>запусков в локальной истории</span><div class="usage-illustration">${runs?`${iconSvg('chart')}<span>Фактические запуски</span>`:'Запуски отобразятся здесь после реального выполнения навыка.'}</div></section><section class="card skill-facts"><h2>Основная информация</h2><div><small>Категория</small><strong>${esc(s.kind||'Пользовательский')}</strong></div><div><small>Владелец</small><strong>${esc(s.author||'Не указан')}</strong></div><div><small>Версия</small><strong>v${esc(s.version)}</strong></div><div><small>Статус</small>${badge(s.approved?'Активен · демо':'Черновик',s.approved?'green':'amber')}</div></section></div><section class="card skill-process"><h2>Как работает навык</h2><div class="skill-flow">${(s.steps||[]).slice(0,4).map((step,i)=>`${i?'<i>→</i>':''}<div><b>${String(i+1).padStart(2,'0')}</b><strong>${esc(step)}</strong></div>`).join('')}</div></section><div class="skill-lower-grid"><section class="card"><h2>Статистика использования</h2><div class="usage-stats"><strong>${runs}<small>запусков</small></strong><span>Подсчёт по локальным операциям браузера</span></div><details class="skill-more"><summary>Посмотреть полную структуру навыка</summary>${more}</details></section><aside class="skill-side-stack"><section class="card"><h2>Жизненный цикл</h2><p class="sub">${esc(s.status)}</p><div class="detail-actions">${!s.approved?`<button class="button primary" data-action="approve" data-id="${esc(id)}">Подтвердить для демо</button>`:''}<button class="button secondary" data-action="history" data-id="${esc(id)}">История версий</button><button class="button secondary" data-action="feedback" data-id="${esc(id)}">Обратная связь</button></div></section><section class="card"><h2>Связанные навыки</h2>${related.map(x=>`<button class="related-skill" data-action="open-skill" data-id="${esc(x.id)}">${miniIcon('▦')}<span>${esc(x.title)}</span><b>→</b></button>`).join('')||'<p class="empty">Других навыков пока нет.</p>'}</section><div class="notice">Учебный Skill. Это не утверждённый регламент компании.</div></aside></div>`);
}
