function landing(){const landingIcons=['<svg viewBox="0 0 32 32"><circle cx="16" cy="10" r="6"/><path d="M5 27c0-6 4.5-10 11-10s11 4 11 10v1H5z"/></svg>','<svg viewBox="0 0 32 32"><path d="m16 3 13 6-13 6L3 9z"/><path d="m4 15 12 6 12-6M4 21l12 6 12-6"/></svg>','<svg viewBox="0 0 32 32"><ellipse cx="16" cy="7" rx="12" ry="4"/><path d="M4 7v18c0 2.2 5.4 4 12 4s12-1.8 12-4V7M4 16c0 2.2 5.4 4 12 4s12-1.8 12-4"/></svg>','<svg viewBox="0 0 32 32"><path d="M18 2 5 18h9l-1 12 14-18h-9z"/></svg>','<svg viewBox="0 0 32 32"><path d="M5 27V18h5v9M14 27V11h5v16M23 27V4h5v23"/></svg>'];document.querySelector('#app').innerHTML=`<div class="exact-landing"><header><button class="exact-logo" data-route="landing"><i></i>Skill Hub</button><nav aria-label="Основная навигация"><button data-route="catalog">Возможности</button><button data-route="workflows">Решения</button><button data-action="landing-info">Тарифы</button><button data-route="knowledge">Блог</button></nav><div><button class="exact-outline" data-route="dashboard">Войти</button><button class="exact-primary" data-route="dashboard">Попробовать бесплатно</button></div></header><main><div class="landing-copy"><span class="landing-pill">Платформа AI-сотрудников</span><h1>Цифровые сотрудники,<br>AI-навыки и автоматизации<br>для роста бизнеса</h1><p>Создавайте AI-сотрудников, используйте готовые навыки,<br>подключайте знания компании и автоматизируйте процессы —<br>в одной платформе.</p><div class="landing-ctas"><button class="exact-primary" data-route="dashboard">Начать <span aria-hidden="true">→</span></button><button class="exact-outline" data-route="dashboard">Запросить демо</button></div></div><div class="landing-original-art" role="img" aria-label="Объёмная стеклянная AI-иллюстрация с кубами"></div></main><footer aria-label="Возможности платформы">${[['Цифровые<br>сотрудники','employees'],['Библиотека<br>навыков','catalog'],['База<br>знаний','knowledge'],['Автоматизации<br>(workflow)','workflows'],['Аналитика<br>и эффективность','analytics']].map(([t,r],index)=>`<button data-route="${r}" aria-label="${t.replace('<br>',' ')}"><i aria-hidden="true">${landingIcons[index]}</i><strong>${t}</strong></button>`).join('')}</footer></div>`}
function dashboard(){
 const recent=[...db.audit.map(x=>({date:x.date,title:x.action,detail:x.target||'Skill'})),...db.operations.map(x=>({date:x.date,title:x.title||x.operation,detail:x.detail||'Локальная операция'}))].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,3);
 const metricRows=[['Цифровые сотрудники','1','users'],['Навыки',db.skills.length,'layers'],['Автоматизации','0','bolt'],['Запусков (30 дн.)',db.operations.filter(o=>Date.now()-new Date(o.date).getTime()<30*86400000).length,'chart']];
 const quickRows=[['spark','Создать навык с AI','describe'],['file','Открыть базу знаний','knowledge'],['workflow','Посмотреть сценарии','workflows'],['chart','Посмотреть аналитику','analytics']];
 const metrics=metricRows.map(([label,value,icon])=>`<article class="ref-kpi"><span class="ref-icon">${iconSvg(icon)}</span><div><small>${label}</small><strong>${value}</strong></div></article>`).join('');
 const quick=quickRows.map(([icon,label,target])=>`<button data-route="${target}"><i>${iconSvg(icon)}</i>${label}</button>`).join('');
 const recentMarkup=recent.length?`<div class="recent-grid">${recent.map(e=>`<article><span class="mini-icon">${iconSvg('activity')}</span><strong>${esc(e.title)}</strong><small>${new Date(e.date).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</small></article>`).join('')}</div>`:'<p class="empty">Здесь появятся сохранённые навыки и выполненные операции.</p>';
 shell(`<div class="eyebrow">ОБЗОР ПЛАТФОРМЫ</div><div class="dashboard-welcome"><div><h1>Добро пожаловать в Skill Hub! 👋</h1><p>Управляйте цифровыми сотрудниками, навыками и процессами</p></div><div class="welcome-art" aria-hidden="true"></div></div><div class="reference-kpis">${metrics}</div><div class="dashboard-middle"><section class="dashboard-ai"><div class="dashboard-ai-copy"><span class="ai-word">AI</span><h2>Создайте навык<br>для цифрового сотрудника</h2><p>Опишите задачу — AI поможет подготовить структуру</p><button class="button light" data-route="describe">Создать навык с AI <span>→</span></button></div><div class="dashboard-robot" role="img" aria-label="Иллюстрация цифрового сотрудника"></div></section><section class="card dashboard-quick"><h2>Быстрые действия</h2>${quick}</section></div><section class="card dashboard-recent"><div class="section-heading"><h2>Последняя активность</h2><button class="text-link" data-route="activity">Все события →</button></div>${recentMarkup}</section>`);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="landing-info"]'))toast('Текущая версия — локальный демонстрационный MVP. Платные тарифы не подключены.')});
render();

